const $=id=>document.getElementById(id);
const escapeHTML=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const lessons={1:{title:'两数之和',concept:'记录与查找',time:'15 分钟',question:'给你一排数字和一个目标数，找出两个不同位置的数字，让它们相加刚好等于目标。返回它们的下标（位置编号从 0 开始）。',think:'如果目标是 10，眼前是 4，你还缺多少？为了不用一次次回头找，可以记下什么？',hints:['先用最笨的方法：每个数字都试着与后面的数字相加。','把问题改成「目标 − 当前数字」：你只需要找这个搭档。','用记录本保存「数字 → 下标」。先查，再记，保证不使用同一个位置两次。'],explain:'把哈希表想成一本能按数字快速查页的记录本。看到 4，缺 6，前面没见过，就记下 4 在位置 0。看到 1，缺 9，同样记下。看到 6，缺 4，记录本已经有 4，于是两人找到搭档。记录本只包含走过的位置，这就是正确性的关键。',complexity:'平均时间 O(n)，额外空间 O(n)。n 是数字个数。每个数字最多看一次，哈希表平均查找很快；用更多记忆换更少的重复查找。',errors:['先存再查：可能让一个数字和自己配对。','返回数字而不是下标：答案要的是位置。','两个相同数字不一定是同一位置：[3,3] 能配成 6。'],examples:[{label:'[3,2,4] → 目标 6',nums:[3,2,4],target:6},{label:'[3,3] → 目标 6',nums:[3,3],target:6},{label:'[0,4,3,0] → 目标 0',nums:[0,4,3,0],target:0},{label:'[4,1,6,8] → 目标 10',nums:[4,1,6,8],target:10}]},20:{title:'有效的括号',concept:'顺序与栈',time:'10 分钟',question:'输入只含 ()[]{} 六种括号。判断是否每个左括号都被同类型的右括号关闭，并且最近打开的要先关闭。返回 true（有效）或 false（无效）。',think:'把括号想成打开几个盒子：最后打开的盒子要最先关。只数左右括号各有几个，真的够吗？试试 ([)]。',hints:['数量相同还不够，([)] 就是反例。','记住还没闭合的左括号。右括号必须先关最近打开的那个。','用栈保存左括号，栈顶在右边。匹配时弹出，空栈或类型不对就失败。读完也要检查栈空。'],explain:'栈就像一摞盘子：新盘子放最上面，取时先取最上面。读到 ( 放进去，再读 [ 放在它上面。接下来 ] 必须先拿走 [，最后 ) 才能拿走 (。如果先出现 )，就碰到了错误的盘子，立刻判定无效。动画与参考代码都保存左括号，栈顶画在右边。',complexity:'时间 O(n)，额外空间 O(n)。n 是字符个数。每个字符看一次，每个左括号最多入栈、出栈一次；全部是左括号时，栈会存下 n 个。',errors:['只检查左右数量：会漏掉交叉和类型错误。','空栈直接取顶部：要先检查是否为空。','读完直接返回 true：还要检查剩余左括号。'],examples:[{label:'([]) · 正确嵌套',s:'([])'},{label:'([)] · 顺序错误',s:'([)]'},{label:'( · 尚未闭合',s:'('},{label:') · 空栈错误',s:')'},{label:'()[]{} · 连续配对',s:'()[]{}'}]}};
let timer=null,index=0,steps=[],currentId=null,example=0;
let records={};let storageOK=true;try{records=JSON.parse(localStorage.getItem('slow-think-v1')||'{}')||{}}catch{storageOK=false}
function day(){const d=new Date();return `${d.getFullYear()}-${d.getMonth()+1}-${d.getDate()}`}
function today(){const key=day();if(!records[key]||!Array.isArray(records[key].list))records[key]={list:[],done:[]};return records[key]}
function save(){if(window.ProgressSync)window.ProgressSync.save(records);else try{localStorage.setItem('slow-think-v1',JSON.stringify(records))}catch{storageOK=false}}
function stop(){if(timer!==null)clearInterval(timer);timer=null;if($('play'))$('play').textContent='播放'}
function add(id){const t=today();if(t.list.includes(id))return;t.list.push(id);save();render()}
let selectedTopic='全部',searchTerm='',view='library';
const topicOrder=['数组与哈希','双指针','滑动窗口','栈','二分与堆','链表','二叉树','回溯与图','动态规划','待分类'];
function understood(id){return Object.values(records).some(r=>r.done?.includes(id))}
function problemRow(p){return `<article class="library-row"><a href="#/problem/${p.id}"><span class="problem-id">${String(p.id).padStart(3,'0')}</span><div><strong>${escapeHTML(p.title.replace(/（简单）|（中等）|（困难）/g,'')||'算法练习')}</strong><small>${p.topic} · ${lessons[p.id]?'完整讲解':'资料已整理'}${understood(p.id)?' · 已理解':''}</small></div><span class="row-arrow">›</span></a></article>`}
function home(){const t=today();return `<div class="page-heading"><h1>${view==='route'?'学习路线':view==='plan'?'我的计划':'题库'}</h1><span class="study-status">${t.done.length} 题已理解</span></div><nav class="view-tabs" aria-label="学习页面"><button data-view="library" class="${view==='library'?'selected':''}">题库</button><button data-view="route" class="${view==='route'?'selected':''}">学习路线</button><button data-view="plan" class="${view==='plan'?'selected':''}">我的计划</button></nav>${view==='library'?`<label class="sr-only" for="search">搜索题号或名称</label><input id="search" type="search" placeholder="搜索题号或名称" value="${escapeHTML(searchTerm)}"><div class="topic-tabs">${['全部',...topicOrder.filter(t=>CONTENT.catalog.some(p=>p.topic===t))].map(topic=>`<button data-topic="${topic}" class="${selectedTopic===topic?'selected':''}">${topic==='二叉树'?'树':topic==='二分与堆'?'二分 / 堆':topic}</button>`).join('')}</div><div id="library-results">${libraryResults()}</div>`:view==='route'?`<p class="route-note">先掌握每类代表题，再练变式。可以自由查看，不受每天五题限制。</p>${topicOrder.filter(topic=>CONTENT.catalog.some(p=>p.topic===topic)).map((topic,i)=>{const items=CONTENT.catalog.filter(p=>p.topic===topic);const rep=items.find(p=>p.representative)||items[0];return `<section class="route-group"><div class="route-heading"><span>${String(i+1).padStart(2,'0')}</span><h2>${topic}</h2></div><div class="route-stage">代表题</div>${problemRow(rep)}${items.length>1?`<details><summary>变式 · ${items.length-1} 题</summary>${items.filter(p=>p!==rep).map(problemRow).join('')}</details>`:''}</section>`}).join('')}`:`<p class="route-note">每日新增目标 5 题；查看和计划数量不限。</p>${t.list.length?t.list.map(id=>`<div class="plan-row">${problemRow(CONTENT.catalog.find(p=>p.id===id)||{id,title:String(id),topic:''})}<button data-remove="${id}">移除</button></div>`).join(''):'<p class="empty-state">还没有安排题目。打开任意题目可加入计划。</p>'}`}<p id="sync-status" role="status" class="sync-status">连接学习记录…</p>`}
function libraryResults(){const items=CONTENT.catalog.filter(p=>(selectedTopic==='全部'||p.topic===selectedTopic)&&(`${p.id} ${p.title}`).toLowerCase().includes(searchTerm.toLowerCase()));return items.map(problemRow).join('')||'<p class="empty-state">没有匹配的题目。</p>'}
function catalogLesson(id){const p=CONTENT.catalog.find(p=>p.id===id);return `<a class="back" href="#">← 题库</a><h1>${p.id} · ${escapeHTML(p.title||'算法练习')}</h1><p class="lesson-meta">${p.topic}</p><section class="coming-lesson"><h2>已有资料，讲解待完善</h2><p>这道题已在整理题库中。完整逐步讲解和五语言参考还未制作，不标为已完成。</p><a class="button" href="https://leetcode.com/problems/" target="_blank" rel="noopener">力扣题库</a></section><button data-add="${id}" ${today().list.includes(id)?'disabled':''}>${today().list.includes(id)?'已在计划':'加入计划'}</button><p id="sync-status" role="status" class="sync-status"></p>`}
function lesson(id){const l=lessons[id],t=today();return `<a class="back" href="#">← 题库</a><h1>${id} · ${l.title}</h1><p class="lesson-meta">简单 · ${l.concept}</p><section class="question"><h2>题目</h2><p>${l.question}</p><div class="example-text"><strong>例子</strong><p>${id===1?'[3,2,4]，目标 6 → [1,2]<br>位置 1 的 2 + 位置 2 的 4 = 6。':'“([])” → true<br>“([)]” → false（不能交叉闭合）。'}</p></div><h2>先想一想</h2><p>${l.think}</p></section><details><summary>提示</summary>${l.hints.map((h,i)=>`<details class="hint"><summary>提示 ${i+1}</summary><p>${h}</p></details>`).join('')}</details><details id="walkthrough"><summary>逐步推演</summary><label for="example" class="sr-only">推演例子</label><select id="example">${l.examples.map((e,i)=>`<option value="${i}">${e.label}</option>`).join('')}</select><div class="board"><div class="board-label">${id===1?'数字卡片 · 寻找搭档':'未闭合的括号 · 栈'}</div><div id="tokens" class="tokens"></div><div id="visual-state"></div><div id="state" class="state"></div></div><div id="step-count" class="muted"></div><div class="progress"><div id="bar"></div></div><div class="controls"><button id="prev">← 上一步</button><button id="play">播放</button><button id="next">下一步 →</button><button id="replay">重播</button></div><p id="step-text" class="step-text" aria-live="polite"></p><p class="muted compact-note">默认暂停，可单步前后查看。</p></details><details><summary>解题思路与复杂度</summary><p>${l.explain}</p><h3>为什么有效？</h3><p>${id===1?'查找时，记录本只包含更早的位置，找到的一对必然是两个不同元素。每次查不到就记下当前元素，不会漏掉之后可能的搭档。':'栈始终保存已打开但还没闭合的左括号。右括号只与最上面的比较，因此严格遵守最近打开的先关闭。'}</p><h3>复杂度</h3><p>${l.complexity}</p></details><details><summary>参考代码</summary><div class="code-head"><label for="language" class="sr-only">代码语言</label><select id="language">${Object.keys(CODES[id]).map(lang=>`<option>${lang}</option>`).join('')}</select><button id="copy">复制</button></div><pre tabindex="0" aria-label="参考代码，可横向滚动"><code id="code"></code></pre><p id="copy-status" role="status" class="muted"></p><p class="muted compact-note">输入遵循题目约束。C# 的 Solution 类可提交力扣；Python 使用函数调用，其余按方法或函数调用。Java 9+；JavaScript / TypeScript 需要支持 Object.hasOwn。</p></details><details><summary>常见错误与自己验算</summary><ul>${l.errors.map(e=>`<li>${e}</li>`).join('')}</ul><p>小挑战：${id===1?'[3,3]，目标 6，答案为什么是 [0,1] 而不是 [0,0]？':'([)] 为什么数量相等却无效？只有一个左括号 (，结束时应返回什么？'}</p></details><section class="completion"><div class="row"><button data-add="${id}" ${t.list.includes(id)?'disabled':''}>${t.list.includes(id)?'已在计划':'加入计划'}</button><button id="done" class="primary">${t.done.includes(id)?'取消「已理解」':'标记已理解'}</button><a class="button" href="#/problem/${id===1?20:1}">另一题 →</a></div><p id="done-status" role="status"></p></section><p id="sync-status" role="status" class="sync-status"></p><details><summary>题目链接</summary><a class="button" href="${CONTENT.catalog.find(p=>p.id===id).officialUrl}" target="_blank" rel="noopener">力扣原题</a></details>`}
function setExample(){stop();index=0;example=Number($('example').value);const e=lessons[currentId].examples[example];steps=currentId===1?Algorithms.twoSumTrace(e.nums,e.target):Algorithms.bracketsTrace(e.s);draw()}
function draw(){const s=steps[index],e=lessons[currentId].examples[example],tokens=currentId===1?e.nums:[...e.s];$('tokens').innerHTML=tokens.map((x,i)=>`<div class="token ${i===s.i?'active':''} ${Array.isArray(s.result)&&s.result.includes(i)?'found':''}">${x}<small>位置 ${i}</small></div>`).join('');$('state').textContent=currentId===1?'记录本（数字 → 下标）\n'+(s.map.map(([v,i])=>`${v} → ${i}`).join('  |  ')||'空'):'栈（底 → 顶）\n'+(s.stack.join('  ')||'空');if($('visual-state'))$('visual-state').innerHTML=currentId===1?`<div class="pair-display"><span>${s.i>=0&&s.i<e.nums.length?e.nums[s.i]:'?'}</span><b>+</b><span class="needed">${s.i>=0&&s.i<e.nums.length?e.target-e.nums[s.i]:'?'}</span><b>=</b><span>${e.target}</span></div><div class="memory-label">已走过的位置</div><div class="memory-cards">${s.map.map(([v,i])=>`<span>${v}<small>位置 ${i}</small></span>`).join('')||'<em>记录本为空</em>'}</div>${Array.isArray(s.result)&&s.result.length?`<div class="result-banner">配对成功：位置 ${s.result.join(' 与 ')}</div>`:''}`:`<div class="stack-visual"><div class="stack-column">${[...s.stack].reverse().map((c,i)=>`<div class="stack-item">${c}${i===0?'<small>栈顶 · 下一个关闭</small>':''}</div>`).join('')||'<div class="stack-empty">栈为空</div>'}<div class="stack-base">栈底</div></div><div class="stack-action">${s.result===false?'× 不匹配 / 未闭合':s.result===true?'✓ 全部配对':s.i>=0&&s.i<e.s.length?`当前字符 <strong>${e.s[s.i]}</strong>`:'等待读取'}<small>最后放入，最先取出</small></div></div>`;$('step-text').textContent=s.text;$('step-count').textContent=`第 ${index+1} / ${steps.length} 步${s.result!==null?' · 结果 '+JSON.stringify(s.result):''}`;$('bar').style.width=((index+1)/steps.length*100)+'%';$('prev').disabled=index===0;$('next').disabled=index===steps.length-1;if(index===steps.length-1)stop()}
function render(){stop();const m=location.hash.match(/^#\/problem\/(\d+)$/);currentId=m&&CONTENT.catalog.some(p=>p.id===Number(m[1]))?Number(m[1]):null;$('app').innerHTML=currentId?(lessons[currentId]?lesson(currentId):catalogLesson(currentId)):home();document.title=currentId?CONTENT.catalog.find(p=>p.id===currentId).title+' · ThinkLab':'ThinkLab · 算法学习';document.querySelectorAll('[data-add]').forEach(b=>b.onclick=()=>add(Number(b.dataset.add)));document.querySelectorAll('[data-remove]').forEach(b=>b.onclick=()=>{const t=today(),id=Number(b.dataset.remove);t.list=t.list.filter(x=>x!==id);t.done=t.done.filter(x=>x!==id);save();render()});if(!storageOK)$('app').insertAdjacentHTML('afterbegin','<p class="notice">浏览器暂时不能保存本地记录；本次仍可学习，刷新可能丢失进度。</p>');document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>{view=b.dataset.view;render()});document.querySelectorAll('[data-topic]').forEach(b=>b.onclick=()=>{selectedTopic=b.dataset.topic;render()});if($('search'))$('search').oninput=()=>{searchTerm=$('search').value;$('library-results').innerHTML=libraryResults()};if(window.ProgressSync)window.ProgressSync.status();if(!currentId||!lessons[currentId])return;setExample();$('example').onchange=setExample;$('prev').onclick=()=>{stop();index=Math.max(0,index-1);draw()};$('next').onclick=()=>{stop();index=Math.min(steps.length-1,index+1);draw()};$('replay').onclick=()=>{stop();index=0;draw()};$('play').onclick=()=>{if(timer!==null){stop();return}if(index===steps.length-1)index=0;draw();$('play').textContent='暂停';timer=setInterval(()=>{index=Math.min(index+1,steps.length-1);draw()},1500)};$('walkthrough').ontoggle=()=>{if(!$('walkthrough').open)stop()};$('language').onchange=()=>{$('code').textContent=CODES[currentId][$('language').value];$('copy-status').textContent=''};$('language').onchange();$('copy').onclick=async()=>{try{await navigator.clipboard.writeText($('code').textContent);$('copy-status').textContent='已复制'}catch{const selection=window.getSelection(),range=document.createRange();range.selectNodeContents($('code'));selection.removeAllRanges();selection.addRange(range);$('copy-status').textContent='浏览器限制了复制，请长按已选中的代码手动复制。'}};$('done').onclick=()=>{const t=today();if(t.done.includes(currentId))t.done=t.done.filter(x=>x!==currentId);else{if(!t.list.includes(currentId)){t.list.push(currentId)}t.done.push(currentId)}save();$('done').textContent=t.done.includes(currentId)?'取消「已理解」':'标记已理解';$('done-status').textContent=window.ProgressSync?'正在保存到共享学习记录…':storageOK?'记录已保存到本机浏览器。':'当前无法保存，刷新可能丢失。'}}
window.addEventListener('hashchange',()=>{render();window.scrollTo(0,0)});window.addEventListener('pagehide',stop);document.addEventListener('visibilitychange',()=>{if(document.hidden)stop()});render();

if(window.ThinkLabBoot)window.ThinkLabBoot.ready();
if(window.ProgressSync)window.ProgressSync.init();
